 private static void verifyDeleteCancellation(CommunityScreen screen){
  var mc=Minecraft.getInstance();var before=screen.data.deepCopy();var transport=ServerMenuClient.previewTransport;
  try{ServerMenuClient.previewTransport=q->{if(Json.opt(q,"op","").equals("delete"))throw new IllegalStateException("Cancel sent a deletion");transport.accept(q);};
   screen.confirm("Удалить объединение?","delete",new JsonObject());
   if(!(mc.screen instanceof UiConfirmDialog))throw new IllegalStateException("Deletion has no confirmation");
   UiInputHarness.escape(mc.screen);
   if(mc.screen!=screen||!screen.data.equals(before))throw new IllegalStateException("Cancellation changed the group or lost its parent");
   System.out.println("RIVET_STAGE_FLOW_OK: group deletion confirmation, cancellation preserves data");
  }finally{ServerMenuClient.previewTransport=transport;}
 }
 private static void stability(ScreenEvent.Render.Post event){if(System.getenv("RIVET_NEXT_UI")==null||stabilityDone)return;var mc=Minecraft.getInstance();if(stabilityScreen==null&&step==1&&event.getScreen() instanceof CommunityScreen screen&&screen.data.has("entries")){stabilityScreen=screen;for(var c:screen.children())if(c instanceof CommunityCard card&&card.getTooltip()!=null)throw new IllegalStateException("Card preview tooltip obscures adjacent cards");if(screen.children().stream().noneMatch(c->c instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().equals(Client.text("ui.create_84370a20"))))throw new IllegalStateException("Group creation has no labelled entry point");stableReply=screen.data.deepCopy();stabilityWidgets=List.copyOf(screen.children());stabilityAt=System.currentTimeMillis();for(var c:screen.children())if(c instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().equals("Обновить")){b.onPress();break;}}else if(stabilityScreen!=null&&System.currentTimeMillis()-stabilityAt>=200){stabilityDone=true;try{if(mc.screen!=stabilityScreen||!stabilityWidgets.equals(stabilityScreen.children()))throw new IllegalStateException("Unchanged response rebuilt group widgets");stabilityScreen.setFocused(null);if(!UiTheme.keyboard(stabilityScreen,264)||!(stabilityScreen.getFocused() instanceof CommunityCard))throw new IllegalStateException("Card keyboard focus failed");int[] choices={0};var popup=new ChoicePopup(stabilityScreen,"Проверка выбора",List.of("Первый","Второй"),n->choices[0]++).current(0);mc.setScreen(popup);((net.minecraft.client.gui.components.Button)popup.children().get(0)).onPress();if(choices[0]!=0||mc.screen!=stabilityScreen)throw new IllegalStateException("Current choice triggered an unnecessary action");mc.setScreen(popup);((net.minecraft.client.gui.components.Button)popup.children().get(1)).onPress();if(choices[0]!=1||mc.screen!=stabilityScreen)throw new IllegalStateException("Changed choice did not trigger exactly one action");UiNavigation.open(stabilityScreen,"home");var home=mc.screen;UiNavigation.open(home,"players");UiNavigation.open(mc.screen,"home");if(mc.screen!=home)throw new IllegalStateException("Navigation lost group page state");System.out.println("RIVET_UI_FLOW_OK: unchanged response retains widgets; keyboard and navigation preserve state; choices dispatch only changed values");}catch(Throwable error){System.out.println("RIVET_UI_FLOW_FAILED");error.printStackTrace();}}}
 static void openPreview(){var mc=Minecraft.getInstance();mc.options.guiScale().set(3);mc.resizeDisplay();CommunityUiHarness.open("normal");original=ServerMenuClient.previewTransport;ServerMenuClient.previewTransport=NextUiHarness::request;mc.setScreen(new CommunityScreen(null,"home",""));}
 private static void verifyThemes(){
  var file=Minecraft.getInstance().gameDirectory.toPath().resolve("rivet/ui-theme.json");
  try{byte[] previous=java.nio.file.Files.exists(file)?java.nio.file.Files.readAllBytes(file):null;
   try{java.nio.file.Files.deleteIfExists(file);UiPalette.reload();if(UiPalette.selected()!=0)throw new IllegalStateException("Default theme is not Golden Dark");
    for(int n=0;n<5;n++){UiPalette.select(n);UiPalette.preview((n+1)%5);UiPalette.reload();if(UiPalette.selected()!=n)throw new IllegalStateException("Theme did not survive reload: "+n);}
    Json.write(file,Map.of("theme","unknown"));UiPalette.reload();if(UiPalette.selected()!=0)throw new IllegalStateException("Unknown theme has no fallback");
    java.nio.file.Files.writeString(file,"broken json");UiPalette.reload();if(UiPalette.selected()!=0)throw new IllegalStateException("Damaged theme has no fallback");
    System.out.println("RIVET_THEMES_OK: default, five persisted choices, unknown and damaged settings fallback");
   }finally{if(previous==null)java.nio.file.Files.deleteIfExists(file);else java.nio.file.Files.write(file,previous);UiPalette.reload();}
  }catch(Exception error){throw new IllegalStateException("Theme persistence failed",error);}
 }
 private static void bounds(){var s=Minecraft.getInstance().screen;
 if(s instanceof CommunityScreen){for(var c:s.children())if(c instanceof AbstractWidget w&&java.util.Set.of("Мои задачи","Поиск по серверу").contains(w.getMessage().getString())&&w.getY()<UiWorkspace.fit(s.width,s.height).page().y()&&!(w instanceof SidebarButton))throw new IllegalStateException("Home toolbar overlaps heading");}
 var widgets=s.children().stream().filter(c->c instanceof AbstractWidget).map(c->(AbstractWidget)c).filter(w->w.visible).toList();
 for(int i=0;i<widgets.size();i++)for(int j=i+1;j<widgets.size();j++){var a=widgets.get(i);var b=widgets.get(j);if(a.getX()<b.getX()+b.getWidth()&&b.getX()<a.getX()+a.getWidth()&&a.getY()<b.getY()+b.getHeight()&&b.getY()<a.getY()+a.getHeight())throw new IllegalStateException(s.getClass().getSimpleName()+" overlapping controls: "+a.getMessage().getString()+" / "+b.getMessage().getString());}
for(var c:s.children())if(c instanceof AbstractWidget w&&w.visible&&(w.getX()<0||w.getY()<0||w.getX()+w.getWidth()>s.width||w.getY()+w.getHeight()>s.height))throw new IllegalStateException(s.getClass().getSimpleName()+" out of bounds: "+w.getMessage().getString());}
